using System.Collections.Immutable;
using System.Reflection;
using CombatSolver.Engine.Common;
using Godot;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using STS2RitsuLib.Combat.Healing;

namespace CombatSolver;

// Research only. This inventories prerequisites and explicitly refuses the
// currently unproved UI call closure; recognized entry methods are not a proof.
internal static class TaskHealthSourceAdmission
{
    private static readonly Guid GameMvid = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly Guid RitsuMvid = new("f7f18a36-8ebb-4db2-b1ea-7bd340579646");
    private const BindingFlags Fields = BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly;
    private static readonly string[] UiTypes =
    [
        "MegaCrit.Sts2.Core.Nodes.Combat.NEndTurnButton",
        "MegaCrit.Sts2.Core.Nodes.Combat.NPlayerHand",
        "MegaCrit.Sts2.Core.Nodes.Combat.NCreatureStateDisplay",
        "MegaCrit.Sts2.Core.Nodes.Orbs.NOrbManager",
        "MegaCrit.Sts2.Core.Nodes.Combat.NEnergyCounter",
        "MegaCrit.Sts2.Core.Nodes.Combat.NIntent",
        "MegaCrit.Sts2.Core.Nodes.Potions.NPotionPopup",
    ];

    internal sealed record Decision(ImmutableArray<string> Refusals, int DirectCallbacks, int TrackerCallbacks,
        int DetailNodes, int DetailCallbacks, int BrowserNodes)
    {
        internal bool Certified => Refusals.Length == 0;
    }

    internal static void Validate(CombatState state)
    {
        Decision result = Capture(state);
        if (!result.Certified)
            throw new PredictionUnsupportedException("Health source proof refused: " + string.Join(";",result.Refusals));
    }

    internal static Decision Capture(CombatState state)
    {
        List<string> refused=[];
        int directCount=0,nestedCount=0,details=0,detailCallbacks=0,nodes=0;
        if(typeof(Creature).Module.ModuleVersionId!=GameMvid)
            return new(["native-version"],0,0,0,0,0);
        var tracker=CombatManager.Instance.StateTracker;
        FieldInfo RequireField(Type type,string name)
            =>type.GetField(name,Fields)??throw new PredictionUnsupportedException("Unknown health source field: "+type.FullName+"."+name);
        MethodInfo RequireMethod(Type type,string name,params Type[] arguments)
            =>type.GetMethod(name,Fields,null,arguments,null)
                ??throw new PredictionUnsupportedException("Unknown health source method: "+type.FullName+"."+name);
        void CheckPatch(MethodInfo method)
        {
            Patches? patches=Harmony.GetPatchInfo(method);
            if(patches is not null && patches.Prefixes.Count+patches.Postfixes.Count+patches.Transpilers.Count+patches.Finalizers.Count!=0)
                refused.Add("patch:"+method.DeclaringType?.FullName+"."+method.Name);
        }
        bool Identity(Delegate callback,Type type,string method,Type[] args)
            =>callback.Target?.GetType()==type &&callback.Method==RequireMethod(type,method,args);
        Type NativeType(string name)=>typeof(Creature).Assembly.GetType(name,true)!;
        Type topbar=NativeType("MegaCrit.sts2.Core.Nodes.TopBar.NTopBarHp");
        Type cubex=NativeType("MegaCrit.Sts2.Core.Models.Monsters.CubexConstruct");
        bool hasUi=false,hasTracker=false;
        foreach(var creature in state.Creatures)
            foreach(string eventName in new[]{"CurrentHpChanged","MaxHpChanged"})
            {
                FieldInfo field=RequireField(typeof(Creature),eventName);
                if(field.FieldType!=typeof(Action<int,int>))
                    throw new PredictionUnsupportedException("Unknown native health event type.");
                if(field.GetValue(creature) is not Action<int,int> audience)continue;
                foreach(Delegate callback in audience.GetInvocationList())
                {
                    directCount++;
                    Type[] args=[typeof(int),typeof(int)];
                    if(Identity(callback,typeof(CombatStateTracker),"OnCreatureValueChanged",args)
                        &&ReferenceEquals(callback.Target,tracker))hasTracker=true;
                    else if(Identity(callback,topbar,"UpdateHealth",args))hasUi=true;
                    else if(eventName=="CurrentHpChanged"&&Identity(callback,typeof(CombatReplayOutcome),"OnHpChanged",args)){}
                    else if(eventName=="CurrentHpChanged"&&Identity(callback,cubex,"OnHpChanged",args))
                        refused.Add("unproven-sfx-call-closure:"+cubex.FullName);
                    else refused.Add("direct:"+eventName+":"+creature.CombatId+":"+callback.Method.DeclaringType?.FullName+"."+callback.Method.Name);
                    CheckPatch(callback.Method);
                }
            }
        foreach(string name in new[]{"set_CurrentHp","set_MaxHp"})CheckPatch(RequireMethod(typeof(Creature),name,typeof(int)));
        foreach(string name in new[]{"SetCurrentHpInternal","SetMaxHpInternal","HealInternal"})CheckPatch(RequireMethod(typeof(Creature),name,typeof(decimal)));
        if(hasTracker)
        {
            if(!ReferenceEquals(RequireField(typeof(CombatStateTracker),"_state").GetValue(tracker),state))
                refused.Add("tracker-state-identity");
            CheckPatch(RequireMethod(typeof(CombatStateTracker),"OnCreatureValueChanged",typeof(int),typeof(int)));
            CheckPatch(RequireMethod(typeof(CombatStateTracker),"CallCombatStateChangedDeferred"));
            CheckPatch(RequireMethod(typeof(PlayerCombatState),"RecalculateCardValues"));
            MethodInfo notify=RequireMethod(typeof(CombatStateTracker),"NotifyCombatStateChanged",typeof(string));
            Patches? patches=Harmony.GetPatchInfo(notify);
            MethodInfo own=RequireMethod(typeof(CombatStateTrackerIsolationPatch),"Prefix",typeof(string));
            if(patches is not null &&(patches.Prefixes.Any(p=>p.PatchMethod!=own)||patches.Prefixes.Count>1
                ||patches.Postfixes.Count+patches.Transpilers.Count+patches.Finalizers.Count!=0))
                refused.Add("patch:tracker-notify");
            CheckPatch(own);
            var audience=RequireField(typeof(CombatStateTracker),"CombatStateChanged").GetValue(tracker) as Action<CombatState>;
            foreach(Delegate callback in audience?.GetInvocationList()??[])
            {
                nestedCount++;
                Type type=callback.Method.DeclaringType!;
                if(type.Module.ModuleVersionId==GameMvid &&UiTypes.Contains(type.FullName,StringComparer.Ordinal)
                    &&Identity(callback,type,"OnCombatStateChanged",[typeof(CombatState)]))
                {
                    hasUi=true;
                    if(type.FullName=="MegaCrit.Sts2.Core.Nodes.Combat.NPlayerHand"
                        &&RequireField(type,"_currentSelectionFilter").GetValue(callback.Target) is not null)
                        refused.Add("hand-selection-filter");
                }
                else if(type.Module.ModuleVersionId==RitsuMvid &&type.FullName=="STS2RitsuLib.Settings.RitsuDebugToolsPanel"
                    &&Identity(callback,type,"OnCombatStateChanged",[typeof(CombatState)]))
                {
                    hasUi=true;
                    object panel=callback.Target!;
                    if(RequireField(type,"<CurrentPageId>k__BackingField").GetValue(panel) is not string page
                        ||page!="com.ritsukage.sts2-RitsuLib:cards")refused.Add("ritsu-unreviewed-page");
                    if(RequireField(type,"_targetPlayerNetId").GetValue(panel) is not ulong target
                        ||!state.Players.Any(p=>p.NetId==target))refused.Add("ritsu-target-player");
                    if(RequireField(type,"_targetPlayerIds").GetValue(panel) is not ulong[] ids
                        ||!ids.SequenceEqual(state.Players.Select(p=>p.NetId)))refused.Add("ritsu-target-player-sequence");
                    foreach(string name in new[]{"ScheduleStateRefresh","RefreshCurrentState","RefreshCreaturePickButton","RefreshHeaderTarget"})
                        CheckPatch(RequireMethod(type,name));
                    CheckPatch(RequireMethod(type,"UpdateTargetDropdown",typeof(IReadOnlyList<Player>),typeof(bool)));
                    CheckPatch(RequireMethod(type,"RefreshLiveDetails",typeof(Node)));
                    Type detailType=typeof(HealHook).Assembly.GetType("STS2RitsuLib.Settings.RitsuDebugLiveDetailContainer",true)!;
                    CheckPatch(RequireMethod(detailType,"RefreshState"));
                    FieldInfo callbacks=RequireField(detailType,"_refreshCallbacks");
                    void Visit(Node node)
                    {
                        nodes++;
                        if(node.GetType()==detailType)
                        {
                            details++;
                            if(callbacks.GetValue(node) is not List<Action> list||list.GetType()!=typeof(List<Action>))
                                throw new PredictionUnsupportedException("Unknown Ritsu detail callback storage.");
                            detailCallbacks+=list.Count;
                            if(list.Count!=0)refused.Add("ritsu-detail-callbacks:"+list.Count);
                        }
                        foreach(Node child in node.GetChildren())Visit(child);
                    }
                    if(RequireField(type,"_currentBrowser").GetValue(panel) is Node browser)Visit(browser);
                    // Game/Godot signals, UI resources and forwarder bodies still
                    // need a separate proof; the observed default page is not it.
                    refused.Add("unproven-ritsu-ui-call-and-signal-closure");
                }
                else refused.Add("tracker:"+type.FullName+"."+callback.Method.Name);
                CheckPatch(callback.Method);
            }
            refused.Add("unproven-card-value-recalculation-closure");
        }
        if(hasUi)refused.Add("unproven-native-ui-call-and-signal-closure");
        return new(refused.Distinct(StringComparer.Ordinal).ToImmutableArray(),directCount,nestedCount,details,detailCallbacks,nodes);
    }
}

