using System.Reflection;
using System.Text.Json;
using Godot;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using STS2RitsuLib.Combat.Healing;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Nodes;
using MegaCrit.Sts2.Core.ValueProps;
namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private static int _taskHealthAuditCallbackCalls;
    private static void TaskUnknownHealthAuditPrefix() => _taskHealthAuditCallbackCalls++;

    private async Task AssertTaskHealthSourceAdmissionAsync(CombatState live,Player player)
    {
        SetStage("task_health_source_admission");
        for(int i=0;i<4;i++) await NGame.Instance.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
        var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();
        string parentBefore=DescribeContinuationContractState(parent,root,player);
        string liveBefore=ContinuationStamp.CaptureLive(live).StateText;
        List<object> cases=[];
        _taskHealthAuditCallbackCalls=0;
        void Refusal(string name,string reason)
        {
            var before=TaskHealthSourceAdmission.Capture(live);
            if(before.Certified||!before.Refusals.Any(r=>r.Contains(reason,StringComparison.Ordinal)))
                throw new InvalidOperationException("Source refusal missing: "+name+":"+reason);
            for(int i=0;i<2;i++)
            {
                try{TaskHealthSourceAdmission.Validate(live);}
                catch(PredictionUnsupportedException e) when(e.Message.Contains(reason,StringComparison.Ordinal)){continue;}
                throw new InvalidOperationException("Source admitted at prospective root/live boundary: "+name);
            }
            cases.Add(new{name,reason,decision=before,prospectiveRootAndLiveRefused=true,productionIntegrated=false});
        }
        Refusal("native-ui-and-recalculation-remain-unknown","unproven-card-value-recalculation-closure");
        void UnknownHealth(int a,int b)=>_taskHealthAuditCallbackCalls++;
        player.Creature.CurrentHpChanged+=UnknownHealth;
        try{Refusal("unknown-player-current","direct:CurrentHpChanged");}
        finally{player.Creature.CurrentHpChanged-=UnknownHealth;}
        player.Creature.MaxHpChanged+=UnknownHealth;
        try{Refusal("unknown-player-maximum","direct:MaxHpChanged");}
        finally{player.Creature.MaxHpChanged-=UnknownHealth;}
        var enemy=live.Enemies.First();
        enemy.CurrentHpChanged+=UnknownHealth;
        try{Refusal("unknown-enemy-current","direct:CurrentHpChanged");}
        finally{enemy.CurrentHpChanged-=UnknownHealth;}
        void UnknownTracker(CombatState state)=>_taskHealthAuditCallbackCalls++;
        var tracker=CombatManager.Instance.StateTracker!;
        tracker.CombatStateChanged+=UnknownTracker;
        try{Refusal("unknown-tracker","tracker:CombatSolver");}
        finally{tracker.CombatStateChanged-=UnknownTracker;}
        const BindingFlags flags=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly;
        var audience=(Delegate)typeof(CombatStateTracker).GetField("CombatStateChanged",flags)!.GetValue(tracker)!;
        var callback=audience.GetInvocationList().Single(c=>c.Method.DeclaringType?.FullName=="STS2RitsuLib.Settings.RitsuDebugToolsPanel");
        var panel=callback.Target!;
        var browser=(Node)panel.GetType().GetField("_currentBrowser",flags)!.GetValue(panel)!;
        Type detailType=typeof(HealHook).Assembly.GetType("STS2RitsuLib.Settings.RitsuDebugLiveDetailContainer",true)!;
        var detail=(Node)Activator.CreateInstance(detailType,true)!;
        detailType.GetMethod("RegisterRefresh",flags)!.Invoke(detail,new object[]{(Action)(()=>_taskHealthAuditCallbackCalls++)});
        browser.AddChild(detail);
        try{Refusal("unknown-nested-detail-with-known-outer-handler","ritsu-detail-callbacks:1");}
        finally{browser.RemoveChild(detail);detail.QueueFree();}
        var harmony=new Harmony("combatsolver.testing.task-health-source-admission");
        MethodInfo prefix=typeof(UnattendedTestRunner).GetMethod(nameof(TaskUnknownHealthAuditPrefix),flags)!;
        foreach(var target in new[]{AccessTools.PropertySetter(typeof(MegaCrit.Sts2.Core.Entities.Creatures.Creature),"CurrentHp"),
            AccessTools.Method(typeof(CombatStateTracker),"NotifyCombatStateChanged",[typeof(string)]),
            AccessTools.Method(typeof(PlayerCombatState),"RecalculateCardValues")})
        {
            try
            {
                harmony.Patch(target,prefix:new HarmonyMethod(prefix));
                Refusal("unknown-patch-"+target.Name,"patch:");
            }
            finally{harmony.Unpatch(target,HarmonyPatchType.All,harmony.Id);}
        }
        int beforeCalls=_taskHealthAuditCallbackCalls;
        var frozen=TaskHealthSourceAdmission.Capture(live);
        if(frozen.Certified)throw new InvalidOperationException("Unproved baseline certified.");
        var children=Enumerable.Range(0,16).Select(_=>parent.Fork()).ToArray();
        player.Creature.CurrentHpChanged+=UnknownHealth;
        try
        {
            await Task.WhenAll(children.Select(child=>Task.Run(()=>
            {
                using var isolation=SimulationNotificationIsolation.Enter();
                if(DescribeContinuationContractState(child,root,player)!=parentBefore
                    ||DescribeContinuationContractState(child.Fork(),root,player)!=parentBefore
                    ||frozen.Certified)
                    throw new InvalidOperationException("Frozen decision/Fork mutated with live audience.");
            })));
        }
        finally{player.Creature.CurrentHpChanged-=UnknownHealth;}
        if(_taskHealthAuditCallbackCalls!=beforeCalls||beforeCalls!=0
            ||DescribeContinuationContractState(parent,root,player)!=parentBefore
            ||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)
            throw new InvalidOperationException("Read-only proof executed callback or changed parent/live.");
        var restored=TaskHealthSourceAdmission.Capture(live);
        if(!restored.Refusals.SequenceEqual(frozen.Refusals))
            throw new InvalidOperationException("Removing only fixture-owned registration did not restore decision.");
        var output=new{cases,restored,callbackCalls=_taskHealthAuditCallbackCalls,
            parallelPrecreatedChildren=16,parentFullStateHistoryRngUnchanged=true,liveFullStateRngUnchanged=true,
            unknownListenersNotInvoked=true,productionIntegrated=false,strictCertificateGranted=false,
            existingRootStillUsesPruningCertificate=root.UsesPruningComponentHealingCertificate,
            productionPrunes=0,searchStarted=false};
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/health-event-source-admission-20261008/source-admission-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("TaskHealthAdmission:EightRefusals:UnknownDirectEnemyTrackerNestedUiAndPatches:NativeUiClosureRefused:NoCallbacks:16FrozenForks:FullParentLiveHistoryRngIsolation:ResearchOnly");
    }

    private async Task AssertTaskHealthUiCallbackCounterexampleAsync(CombatState live, Player player)
    {
        SetStage("task_health_ui_callback_counterexample");
        await CreatureCmd.SetMaxHp(player.Creature,75);
        await CreatureCmd.SetCurrentHp(player.Creature,60);
        foreach(var potion in player.PotionSlots.ToArray()) potion?.Discard();
        for(int i=0;i<4;i++) await NGame.Instance.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
        const BindingFlags flags=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly;
        var tracker=CombatManager.Instance.StateTracker;
        var trackerField=typeof(CombatStateTracker).GetField("CombatStateChanged",flags)!;
        var callback=((Delegate)trackerField.GetValue(tracker)!).GetInvocationList()
            .Single(c=>c.Method.DeclaringType?.FullName=="STS2RitsuLib.Settings.RitsuDebugToolsPanel");
        var panel=callback.Target!;
        var browser=(Node)panel.GetType().GetField("_currentBrowser",flags)!.GetValue(panel)!;
        var detailType=typeof(HealHook).Assembly.GetType("STS2RitsuLib.Settings.RitsuDebugLiveDetailContainer",true)!;
        var detail=(Node)Activator.CreateInstance(detailType,true)!;
        bool armed=false,healed=false;int calls=0;
        void UnknownDetailRefresh()
        {
            if(!armed)return;
            calls++;
            if(!healed && player.Creature.CurrentHp<60)
            {
                healed=true;
                player.Creature.HealInternal(2);
            }
        }
        detailType.GetMethod("RegisterRefresh",flags)!.Invoke(detail,new object[]{(Action)UnknownDetailRefresh});
        var directFields=new[]{typeof(MegaCrit.Sts2.Core.Entities.Creatures.Creature).GetField("CurrentHpChanged",flags)!,
            typeof(MegaCrit.Sts2.Core.Entities.Creatures.Creature).GetField("MaxHpChanged",flags)!};
        object?[] directBefore=directFields.Select(f=>f.GetValue(player.Creature)).ToArray();
        object? trackerBefore=trackerField.GetValue(tracker);
        browser.AddChild(detail);
        try
        {
            if(directFields.Where((f,i)=>!Equals(f.GetValue(player.Creature),directBefore[i])).Any()
                ||!Equals(trackerBefore,trackerField.GetValue(tracker)))
                throw new InvalidOperationException("Detail setup changed a direct/tracker subscription.");
            var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();var child=parent.Fork();
            string parentBefore=DescribeContinuationContractState(parent,root,player);
            string liveBefore=ContinuationStamp.CaptureLive(live).StateText;
            int reviewed=StrategicHpRecoveryBound.ComponentHealingUpperBound(parent,player,0,useReviewedSources:true);
            if(!root.UsesPruningComponentHealingCertificate || reviewed!=0)
                throw new InvalidOperationException("Expected existing zero recovery certificate: "+root.PruningComponentHealingRejection);
            armed=true;
            using(SimulationNotificationIsolation.Enter()) child.Damage(player.Creature,6,ValueProp.Unblockable|ValueProp.Unpowered,null);
            int shadowHp=child.State.GetCreature(player.Creature).CurrentHp;
            if(calls!=0 || DescribeContinuationContractState(parent,root,player)!=parentBefore
                || ContinuationStamp.CaptureLive(live).StateText!=liveBefore)
                throw new InvalidOperationException("Shadow invoked detail callback or mutated parent/live.");
            await CreatureCmd.Damage(new BlockingPlayerChoiceContext(),player.Creature,6,ValueProp.Unblockable|ValueProp.Unpowered,null!);
            for(int i=0;i<10&&!healed;i++) await NGame.Instance.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
            if(!healed || calls<1 || player.Creature.CurrentHp!=shadowHp+2
                || DescribeContinuationContractState(parent,root,player)!=parentBefore)
                throw new InvalidOperationException("Nested native detail callback counterexample did not reproduce.");
            var registries=new[]{"STS2RitsuLib.Diagnostics.DebugTools.RitsuDebugToolsPageRegistry",
                "STS2RitsuLib.Combat.SecondaryResources.ModSecondaryResourceRegistry"}.Select(name=>
            {
                Type type=typeof(HealHook).Assembly.GetType(name,true)!;
                object sync=type.GetField("SyncRoot",flags)!.GetValue(null)!;
                using(((System.Threading.Lock)sync).EnterScope())
                    return new{type=name,fields=type.GetFields(flags).Where(f=>f.IsStatic
                        &&f.FieldType.IsGenericType&&f.FieldType.GetGenericTypeDefinition()==typeof(Dictionary<,>))
                        .Select(f=>new{f.Name,count=((System.Collections.IDictionary)f.GetValue(null)!).Count}).ToArray()};
            }).ToArray();
            var output=new{reviewedBound=reviewed,root.UsesPruningComponentHealingCertificate,root.UsesKnownNativeHealingPolicy,
                shadowHp,nativeHp=player.Creature.CurrentHp,calls,unmodeledHeal=2,directAndTrackerAudienceUnchanged=true,
                shadowDidNotInvokeCallback=true,parentFullStateHistoryRngUnchanged=true,
                currentPageId=panel.GetType().GetField("<CurrentPageId>k__BackingField",flags)!.GetValue(panel),
                callbackCount=((List<Action>)detailType.GetField("_refreshCallbacks",flags)!.GetValue(detail)!).Count,
                registries,productionPrunes=0,searchStarted=false};
            File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/health-event-source-admission-20261008/ui-callback-counterexample.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
            _completedChecks.Add("TaskHealthUiCallback:NativeRitsuDefaultPage:DirectAndTrackerAudienceUnchanged:ZeroCertificateTwoHeal:ShadowAndParentIsolated");
        }
        finally
        {
            armed=false;
            browser.RemoveChild(detail);
            detail.QueueFree();
        }
    }

    private void AssertTaskHealthUiAdmissionInventory(CombatState live, Player player)
    {
        SetStage("task_health_ui_admission_inventory");
        string before=ContinuationStamp.CaptureLive(live).StateText;
        const BindingFlags all=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly;
        object DescribeValue(object? value)
        {
            if(value is Delegate d)return new{type=value.GetType().FullName,handlers=d.GetInvocationList().Select(c=>new{type=c.Method.DeclaringType?.FullName,c.Method.Name,targetType=c.Target?.GetType().FullName}).ToArray()};
            if(value is null||value is string||value is bool||value is int||value is uint||value is ulong)return new{type=value?.GetType().FullName,value};
            if(value is Array a)return new{type=value.GetType().FullName,length=a.Length};
            return new{type=value.GetType().FullName};
        }
        object DescribeNode(Node node)=>new{type=node.GetType().FullName,
            fields=node.GetType().GetFields(all).Where(f=>!f.IsStatic&&typeof(Delegate).IsAssignableFrom(f.FieldType)).Select(f=>new{f.Name,value=DescribeValue(f.GetValue(node))}).ToArray(),
            children=node.GetChildren().Select(DescribeNode).ToArray()};
        var nested=typeof(CombatStateTracker).GetField("CombatStateChanged",all)!.GetValue(CombatManager.Instance.StateTracker) as Delegate;
        var debug=nested?.GetInvocationList().SingleOrDefault(c=>c.Method.DeclaringType?.FullName=="STS2RitsuLib.Settings.RitsuDebugToolsPanel");
        var type=debug?.Target?.GetType();
        var rows=type?.GetFields(all).Where(f=>!f.IsStatic).Select(f=>new{f.Name,fieldType=f.FieldType.FullName,value=DescribeValue(f.GetValue(debug!.Target))}).ToArray();
        Node? browser=type?.GetField("_currentBrowser",all)?.GetValue(debug?.Target) as Node;
        var assembly=typeof(HealHook).Assembly;
        var registries=assembly.GetTypes().Where(t=>t.Name is "RitsuDebugToolsPageRegistry" or "ModSecondaryResourceRegistry" or "RitsuDebugToolsPageDefinition").Select(t=>new{t.FullName,
            staticFields=t.GetFields(all).Where(f=>f.IsStatic).Select(f=>new{f.Name,fieldType=f.FieldType.FullName,value=DescribeValue(f.GetValue(null))}).ToArray()}).ToArray();
        var patchTypes=new[]{typeof(CombatStateTracker),typeof(MegaCrit.Sts2.Core.Entities.Creatures.Creature),typeof(PlayerCombatState)};
        var patches=Harmony.GetAllPatchedMethods().Where(m=>patchTypes.Contains(m.DeclaringType)).Select(m=>new{type=m.DeclaringType?.FullName,target=m.ToString(),patches=Harmony.GetPatchInfo(m)?.Prefixes.Concat(Harmony.GetPatchInfo(m)!.Postfixes).Concat(Harmony.GetPatchInfo(m)!.Transpilers).Concat(Harmony.GetPatchInfo(m)!.Finalizers).Select(p=>new{p.owner,method=p.PatchMethod.ToString(),type=p.PatchMethod.DeclaringType?.FullName}).ToArray()}).ToArray();
        var output=new{debugPresent=debug!=null,debugFields=rows,browserTree=browser is null?null:DescribeNode(browser),registries,patches,
            playerIds=live.Players.Select(p=>p.NetId).ToArray(),readonlyLiveUnchanged=before==ContinuationStamp.CaptureLive(live).StateText};
        if(!output.readonlyLiveUnchanged)throw new InvalidOperationException("Health UI inventory mutated live state.");
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/health-event-source-admission-20261008/health-ui-inventory.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("HealthUiInventory:ActualFieldsAndBrowserTree:RegistriesAndNativeHealthPatches:LiveUnchanged");
    }
}

