	public void StartSfxLoop(string sfxName, string loopParam, float loopStopValue)
	{
		if (!_sfxLoops.ContainsKey(sfxName))
		{
			_sfxLoops.Add(sfxName, (loopParam, loopStopValue));
			SfxCmd.PlayLoop(sfxName, usesLoopParam: false);
		}
