using STS2RitsuLib.Content;
using STS2RitsuLib.Scaffolding.Godot.NodeAttachments;

namespace STS2RitsuLib.Combat.SecondaryResources;

/// <summary>
///     <para xml:lang="en">Registers secondary combat resources owned by one mod.</para>
///     <para xml:lang="zh-CN">注册由一个模组所有的次级战斗资源。</para>
/// </summary>
public sealed class ModSecondaryResourceRegistry
{
	private sealed record CombatUiVisibilityPredicateRegistration(int Order, long Sequence, SecondaryResourceCombatUiVisibilityPredicate Predicate);

	private const string IdTypeStem = "SECONDARY_RESOURCE";

	private static readonly Lock SyncRoot = new Lock();

	private static readonly Dictionary<string, ModSecondaryResourceRegistry> Registries = new Dictionary<string, ModSecondaryResourceRegistry>(StringComparer.OrdinalIgnoreCase);

	private static readonly Dictionary<string, SecondaryResourceDefinition> Definitions = new Dictionary<string, SecondaryResourceDefinition>(StringComparer.OrdinalIgnoreCase);

	private static readonly Dictionary<string, List<CombatUiVisibilityPredicateRegistration>> CombatUiVisibilityPredicates = new Dictionary<string, List<CombatUiVisibilityPredicateRegistration>>(StringComparer.OrdinalIgnoreCase);

	private static long _nextVisibilityPredicateSequence;

	private readonly string _modId;

	/// <summary>
	///     <para xml:lang="en">Gets whether at least one secondary resource is registered.</para>
	///     <para xml:lang="zh-CN">获取是否至少注册了一个次级资源。</para>
	/// </summary>
	public static bool HasAny
	{
		get
		{
			using (SyncRoot.EnterScope())
			{
				return Definitions.Count > 0;
			}
		}
	}

	private ModSecondaryResourceRegistry(string modId)
	{
		_modId = modId;
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Gets the registry for <paramref name="modId" />. Leading and trailing whitespace is ignored.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         获取 <paramref name="modId" /> 的注册表；忽略首尾空白。
	///     </para>
	/// </summary>
	public static ModSecondaryResourceRegistry For(string modId)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
		string text = modId.Trim();
		using (SyncRoot.EnterScope())
		{
			if (Registries.TryGetValue(text, out ModSecondaryResourceRegistry value))
			{
				return value;
			}
			ModSecondaryResourceRegistry modSecondaryResourceRegistry = new ModSecondaryResourceRegistry(text);
			Registries[text] = modSecondaryResourceRegistry;
			return modSecondaryResourceRegistry;
		}
	}

	/// <summary>
	///     <para xml:lang="en">Builds a full resource ID from a mod ID and mod-local ID.</para>
	///     <para xml:lang="zh-CN">根据模组 ID 和模组内 ID 构建完整资源 ID。</para>
	/// </summary>
	public static string GetResourceId(string modId, string localId)
	{
		return ModContentRegistry.GetCompoundId(modId, "SECONDARY_RESOURCE", localId);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Registers a secondary resource and returns its mod-bound definition. Repeating the same registration
	///         returns the definition registered first.
	///     </para>
	///     <para xml:lang="zh-CN">注册次级资源并返回绑定到模组后的定义；重复注册同一资源时返回最先注册的定义。</para>
	/// </summary>
	public SecondaryResourceDefinition Register(string localId, SecondaryResourceDefinition definition)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(localId, "localId");
		ArgumentNullException.ThrowIfNull(definition, "definition");
		SecondaryResourceDefinition secondaryResourceDefinition = definition.Bind(_modId, localId);
		using (SyncRoot.EnterScope())
		{
			if (Definitions.TryGetValue(secondaryResourceDefinition.Id, out SecondaryResourceDefinition value))
			{
				if (!StringComparer.OrdinalIgnoreCase.Equals(value.ModId, _modId))
				{
					throw new InvalidOperationException($"Secondary resource '{secondaryResourceDefinition.Id}' is already registered by mod '{value.ModId}'.");
				}
				return value;
			}
			Definitions[secondaryResourceDefinition.Id] = secondaryResourceDefinition;
		}
		RitsuLibFramework.Logger.Info($"[SecondaryResource] Registered {secondaryResourceDefinition.Id} (mod={secondaryResourceDefinition.ModId}).", 1);
		return secondaryResourceDefinition;
	}

	/// <summary>
	///     <para xml:lang="en">Attempts to get a registered definition by full resource ID.</para>
	///     <para xml:lang="zh-CN">尝试按完整资源 ID 获取已注册定义。</para>
	/// </summary>
	public static bool TryGet(string resourceId, out SecondaryResourceDefinition definition)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
		using (SyncRoot.EnterScope())
		{
			return Definitions.TryGetValue(resourceId.Trim(), out definition);
		}
	}

	/// <summary>
	///     <para xml:lang="en">Gets a registered definition, or throws when the ID is unknown.</para>
