	/// </summary>
	public void RegisterCombatUiAlwaysVisibleWhen(string localId, SecondaryResourceCombatUiVisibilityPredicate predicate, int order = 0)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(localId, "localId");
		ArgumentNullException.ThrowIfNull(predicate, "predicate");
		string resourceId = GetResourceId(_modId, localId);
		using (SyncRoot.EnterScope())
		{
			if (!CombatUiVisibilityPredicates.TryGetValue(resourceId, out List<CombatUiVisibilityPredicateRegistration> value))
			{
				value = new List<CombatUiVisibilityPredicateRegistration>();
				CombatUiVisibilityPredicates[resourceId] = value;
			}
			value.Add(new CombatUiVisibilityPredicateRegistration(order, _nextVisibilityPredicateSequence++, predicate));
			value.Sort(delegate(CombatUiVisibilityPredicateRegistration left, CombatUiVisibilityPredicateRegistration right)
			{
				int num = left.Order.CompareTo(right.Order);
