	private static NodeAttachmentOptions WithDefaultCardUiOptions(NodeAttachmentOptions? options)
	{
		NodeAttachmentOptions nodeAttachmentOptions = options ?? NodeAttachmentOptions.Default;
		return new NodeAttachmentOptions
		{
			Name = nodeAttachmentOptions.Name,
			Order = nodeAttachmentOptions.Order,
			UniqueNameInOwner = nodeAttachmentOptions.UniqueNameInOwner,
			IncludeDerivedParentTypes = nodeAttachmentOptions.IncludeDerivedParentTypes,
			DuplicatePolicy = nodeAttachmentOptions.DuplicatePolicy,
			AddMode = nodeAttachmentOptions.AddMode,
			AttachParentSelector = (nodeAttachmentOptions.AttachParentSelector ?? new Func<Node, Node>(ResolveCardUiAttachParent)),
			SetupTiming = nodeAttachmentOptions.SetupTiming,
			ChildIndex = nodeAttachmentOptions.ChildIndex,
			InsertBeforeName = nodeAttachmentOptions.InsertBeforeName,
			InsertAfterName = nodeAttachmentOptions.InsertAfterName,
			QueueFreeReplacedNode = nodeAttachmentOptions.QueueFreeReplacedNode
		};
	}

	private static NodeAttachmentOptions WithDefaultMultiplayerPlayerStateOptions(NodeAttachmentOptions? options)
	{
		NodeAttachmentOptions nodeAttachmentOptions = options ?? NodeAttachmentOptions.Default;
