		{
			Name = nodeAttachmentOptions.Name,
			Order = nodeAttachmentOptions.Order,
			UniqueNameInOwner = nodeAttachmentOptions.UniqueNameInOwner,
			IncludeDerivedParentTypes = nodeAttachmentOptions.IncludeDerivedParentTypes,
			DuplicatePolicy = nodeAttachmentOptions.DuplicatePolicy,
			AddMode = nodeAttachmentOptions.AddMode,
			AttachParentSelector = (nodeAttachmentOptions.AttachParentSelector ?? new Func<Node, Node>(ResolveMultiplayerPlayerStateAttachParent)),
			SetupTiming = NodeAttachmentSetupTiming.AfterAdd,
			ChildIndex = nodeAttachmentOptions.ChildIndex,
			InsertBeforeName = nodeAttachmentOptions.InsertBeforeName,
			InsertAfterName = nodeAttachmentOptions.InsertAfterName,
			QueueFreeReplacedNode = nodeAttachmentOptions.QueueFreeReplacedNode
		};
	}

	private static Node ResolveCardUiAttachParent(Node parent)
	{
		NCard val = (NCard)(object)((parent is NCard) ? parent : null);
		if (val != null)
		{
			Control body = val.Body;
			if (body != null)
			{
				return (Node)(object)body;
			}
		}
		return parent;
	}

	private static Node ResolveMultiplayerPlayerStateAttachParent(Node parent)
	{
		NMultiplayerPlayerState val = (NMultiplayerPlayerState)(object)((parent is NMultiplayerPlayerState) ? parent : null);
		if (val != null)
		{
			HBoxContainer nodeOrNull = ((Node)val).GetNodeOrNull<HBoxContainer>(NodePath.op_Implicit("TopInfoContainer"));
			if (nodeOrNull != null)
			{
				return (Node)(object)nodeOrNull;
			}
		}
		return parent;
	}
}
