using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace STS2RitsuLib.Diagnostics.DebugTools;

/// <summary>
///     <para xml:lang="en">
///         Registers independently owned pages for the visual developer-tools dock without replacing built-in or
///         other mods' pages.
///     </para>
///     <para xml:lang="zh-CN">
///         为可视化开发者工具停靠面板注册独立所有权页面，且不会替换内置页面或其他模组的页面。
///     </para>
/// </summary>
public static class RitsuDebugToolsPageRegistry
{
	private sealed class Registration(RitsuDebugToolsPageDefinition definition) : IDisposable
	{
		private int _disposed;

		internal RitsuDebugToolsPageDefinition Definition { get; } = definition;

		public void Dispose()
		{
			if (Interlocked.Exchange(ref _disposed, 1) != 0)
			{
				return;
			}
			bool flag = false;
			using (SyncRoot.EnterScope())
			{
				if (Pages.TryGetValue(Definition.QualifiedId, out Registration value) && value == this)
				{
					flag = Pages.Remove(Definition.QualifiedId);
				}
			}
			if (flag)
			{
				NotifyChanged();
			}
		}
	}

	private const int MaximumPageCount = 256;

	private const int MaximumIdentityLength = 128;

	private const int MaximumSortOrder = 100000;

	private static readonly Dictionary<string, Registration> Pages = new Dictionary<string, Registration>(StringComparer.OrdinalIgnoreCase);

	private static readonly HashSet<string> ReservedQualifiedIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
	{
		"com.ritsukage.sts2-RitsuLib:cards", "com.ritsukage.sts2-RitsuLib:pile-cards", "com.ritsukage.sts2-RitsuLib:relics", "com.ritsukage.sts2-RitsuLib:potions", "com.ritsukage.sts2-RitsuLib:powers", "com.ritsukage.sts2-RitsuLib:secondary-resources", "com.ritsukage.sts2-RitsuLib:players", "com.ritsukage.sts2-RitsuLib:creatures", "com.ritsukage.sts2-RitsuLib:monsters", "com.ritsukage.sts2-RitsuLib:rooms",
		"com.ritsukage.sts2-RitsuLib:encounters", "com.ritsukage.sts2-RitsuLib:events", "com.ritsukage.sts2-RitsuLib:state-presets"
	};

	private static readonly Lock SyncRoot = new Lock();

	internal static event Action? Changed;

	/// <summary>
	///     <para xml:lang="en">
	///         Registers a page and returns an ownership handle. Disposing the handle removes only that exact
	///         registration. Duplicate qualified IDs are rejected rather than replaced.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册页面并返回所有权句柄。释放句柄时只移除该次注册；重复的全局 ID 会被拒绝而不会覆盖原页面。
	///     </para>
	/// </summary>
	/// <param name="definition">
	///     <para xml:lang="en">The immutable page definition to validate and register.</para>
	///     <para xml:lang="zh-CN">要校验并注册的不可变页面定义。</para>
	/// </param>
	/// <returns>
	///     <para xml:lang="en">An idempotent handle that unregisters this page when disposed.</para>
	///     <para xml:lang="zh-CN">释放时取消注册当前页面的幂等句柄。</para>
	/// </returns>
	/// <exception cref="T:System.ArgumentException">
	///     <para xml:lang="en">
	///         Thrown when identity text is malformed, the qualified ID is reserved, or it already exists.
	///     </para>
	///     <para xml:lang="zh-CN">当标识文本格式无效、全局 ID 已保留或已存在时抛出。</para>
	/// </exception>
	/// <exception cref="T:System.ArgumentNullException">
	///     <para xml:lang="en">Thrown when <paramref name="definition" /> is null.</para>
	///     <para xml:lang="zh-CN">当 <paramref name="definition" /> 为 null 时抛出。</para>
	/// </exception>
	/// <exception cref="T:System.ArgumentOutOfRangeException">
	///     <para xml:lang="en">
	///         Thrown when the sort order, preferred width, or total page count exceeds its supported bound.
	///     </para>
	///     <para xml:lang="zh-CN">当排序值、期望宽度或页面总数超过支持范围时抛出。</para>
	/// </exception>
	public static IDisposable Register(RitsuDebugToolsPageDefinition definition)
	{
		ArgumentNullException.ThrowIfNull(definition, "definition");
		ValidateIdentity(definition.ModId, "ModId");
		ValidateIdentity(definition.Id, "Id");
		int sortOrder = definition.SortOrder;
		if ((sortOrder < -100000 || sortOrder > 100000) ? true : false)
		{
			throw new ArgumentOutOfRangeException("definition", definition.SortOrder, $"Developer-tools page order must be between {-100000} and {100000}.");
		}
		float preferredWidthFraction = definition.PreferredWidthFraction;
		bool flag = ((preferredWidthFraction < 0.35f || preferredWidthFraction > 0.9f) ? true : false);
		if (flag || !float.IsFinite(definition.PreferredWidthFraction))
		{
			throw new ArgumentOutOfRangeException("definition", definition.PreferredWidthFraction, "Developer-tools page width fraction must be between 0.35 and 0.90.");
		}
		if (ReservedQualifiedIds.Contains(definition.QualifiedId))
		{
			throw new ArgumentException("Developer-tools page '" + definition.QualifiedId + "' is reserved by RitsuLib.", "definition");
		}
		Registration registration = new Registration(definition);
		using (SyncRoot.EnterScope())
		{
			if (Pages.ContainsKey(definition.QualifiedId))
			{
				throw new ArgumentException("Developer-tools page '" + definition.QualifiedId + "' is already registered.", "definition");
			}
			if (Pages.Count >= 256)
			{
				throw new ArgumentOutOfRangeException("definition", Pages.Count, $"No more than {256} developer-tools pages may be registered.");
			}
			Pages.Add(definition.QualifiedId, registration);
		}
		NotifyChanged();
		return registration;
	}

	/// <summary>
	///     <para xml:lang="en">Returns an immutable, deterministically ordered snapshot of registered pages.</para>
	///     <para xml:lang="zh-CN">返回已注册页面的不可变确定顺序快照。</para>
	/// </summary>
	public static IReadOnlyList<RitsuDebugToolsPageDefinition> GetPages()
	{
		using (SyncRoot.EnterScope())
		{
			return Array.AsReadOnly((from registration in Pages.Values
				select registration.Definition into definition
				orderby definition.SortOrder
				select definition).ThenBy<RitsuDebugToolsPageDefinition, string>((RitsuDebugToolsPageDefinition definition) => definition.ModId, StringComparer.OrdinalIgnoreCase).ThenBy<RitsuDebugToolsPageDefinition, string>((RitsuDebugToolsPageDefinition definition) => definition.Id, StringComparer.OrdinalIgnoreCase).ToArray());
		}
	}

	private static void ValidateIdentity(string value, string paramName)
	{
		if (value.Length > 128)
		{
			throw new ArgumentException($"Developer-tools identity components cannot exceed {128} characters.", paramName);
		}
		if (value.Any(delegate(char character)
		{
			bool flag = char.IsAsciiLetterOrDigit(character);
			if (!flag)
			{
				bool flag2 = ((character == '-' || character == '.' || character == '_') ? true : false);
				flag = flag2;
			}
			return !flag;
		}))
		{
			throw new ArgumentException("Developer-tools identity components may contain only ASCII letters, digits, '.', '_', and '-'.", paramName);
		}
	}

	private static void NotifyChanged()
	{
		try
		{
			RitsuDebugToolsPageRegistry.Changed?.Invoke();
		}
		catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
		{
			RitsuLibFramework.Logger.Warn($"[DebugToolsUi] Page-registry refresh callback failed: {ex}", 1);
		}
	}
}
